	}

	if unaryExpr.Operator != "-" {
		t.Errorf("Expected '-', got '%s'", unaryExpr.Operator)
	}
}

func TestParseFunctionCall(t *testing.T) {
	input := "fn main() { let result = add(10, 20); }"
	lex, _ := lexer.New(input)
	tokens, _ := lex.Tokenize()
	parser := New(tokens)
