package lexer

import (
	"fmt"
	"strings"
	"unicode"
)

const (
	maxInputSize      = 10_000_000
	maxIdentifierLen  = 10_000
	maxStringLen      = 1_000_000
	maxNumberLen      = 100
)

// Lexer tokenizes V-compatible source code
type Lexer struct {
	input     string
	pos       int
	line      int
	column    int
	keywords  map[string]TokenType
}

// New creates a new lexer with input validation
func New(input string) (*Lexer, error) {
	// 보안: 입력 크기 제한
	if len(input) > maxInputSize {
		return nil, fmt.Errorf("input too large: %d bytes (max %d)", len(input), maxInputSize)
	}

	// 보안: NULL 바이트 확인 (단일 바이트로 검사)
	for _, r := range input {
		if r == 0 {
			return nil, fmt.Errorf("input contains null bytes")
		}
	}

	keywords := map[string]TokenType{
		"fn":        TknFn,
		"let":       TknLet,
		"mut":       TknMut,
		"const":     TknConst,
		"if":        TknIf,
		"else":      TknElse,
		"for":       TknFor,
		"in":        TknIn,
		"match":     TknMatch,
		"type":      TknType,
		"struct":    TknStruct,
		"interface": TknInterface,
		"enum":      TknEnum,
		"trait":     TknTrait,
		"impl":      TknImpl,
		"return":    TknReturn,
		"module":    TknModule,
		"import":    TknImport,
		"true":      TknTrue,
		"false":     TknFalse,
		"none":      TknNone,
	}

	return &Lexer{
		input:    input,
		pos:      0,
		line:     1,
		column:   1,
		keywords: keywords,
	}, nil
}

// Tokenize returns all tokens from the input
func (l *Lexer) Tokenize() ([]Token, error) {
	var tokens []Token

	for {
		l.skipWhitespaceAndComments()

		if l.isAtEnd() {
			tokens = append(tokens, Token{
				Type:   TknEof,
				Text:   "",
				Line:   l.line,
				Column: l.column,
			})
			break
		}

		token, err := l.nextToken()
		if err != nil {
			return nil, err
		}
		tokens = append(tokens, token)
	}

	return tokens, nil
}

func (l *Lexer) nextToken() (Token, error) {
	startLine := l.line
	startColumn := l.column
	startPos := l.pos

	ch := l.current()
	var token Token

	switch ch {
	case '(':
		l.advance()
		token = Token{TknLParen, "(", startLine, startColumn}
	case ')':
		l.advance()
		token = Token{TknRParen, ")", startLine, startColumn}
	case '{':
		l.advance()
		token = Token{TknLBrace, "{", startLine, startColumn}
	case '}':
		l.advance()
		token = Token{TknRBrace, "}", startLine, startColumn}
	case '[':
		l.advance()
		token = Token{TknLBracket, "[", startLine, startColumn}
	case ']':
		l.advance()
		token = Token{TknRBracket, "]", startLine, startColumn}
	case ',':
		l.advance()
		token = Token{TknComma, ",", startLine, startColumn}
	case ';':
		l.advance()
		token = Token{TknSemicolon, ";", startLine, startColumn}
	case '@':
		l.advance()
		token = Token{TknAt, "@", startLine, startColumn}
	case '~':
		l.advance()
		token = Token{TknTilde, "~", startLine, startColumn}
	case '+':
		l.advance()
		if l.current() == '=' {
			l.advance()
			token = Token{TknPlusAssign, "+=", startLine, startColumn}
		} else {
			token = Token{TknPlus, "+", startLine, startColumn}
		}
	case '-':
		l.advance()
		switch l.current() {
		case '=':
			l.advance()
			token = Token{TknMinusAssign, "-=", startLine, startColumn}
		case '>':
			l.advance()
			token = Token{TknArrow, "->", startLine, startColumn}
		default:
			token = Token{TknMinus, "-", startLine, startColumn}
		}
	case '*':
		l.advance()
		if l.current() == '=' {
			l.advance()
			token = Token{TknStarAssign, "*=", startLine, startColumn}
		} else {
			token = Token{TknStar, "*", startLine, startColumn}
		}
	case '/':
		l.advance()
		if l.current() == '=' {
			l.advance()
			token = Token{TknSlashAssign, "/=", startLine, startColumn}
		} else {
			token = Token{TknSlash, "/", startLine, startColumn}
		}
	case '%':
		l.advance()
		token = Token{TknPercent, "%", startLine, startColumn}
	case '^':
		l.advance()
		token = Token{TknCaret, "^", startLine, startColumn}
	case '&':
		l.advance()
		if l.current() == '&' {
			l.advance()
			token = Token{TknLogicalAnd, "&&", startLine, startColumn}
		} else {
			token = Token{TknAmpersand, "&", startLine, startColumn}
		}
	case '|':
		l.advance()
		if l.current() == '|' {
			l.advance()
			token = Token{TknLogicalOr, "||", startLine, startColumn}
		} else {
			token = Token{TknPipe, "|", startLine, startColumn}
		}
	case '!':
		l.advance()
		if l.current() == '=' {
			l.advance()
			token = Token{TknNe, "!=", startLine, startColumn}
		} else {
			token = Token{TknNot, "!", startLine, startColumn}
		}
	case '?':
		l.advance()
		token = Token{TknQuestion, "?", startLine, startColumn}
	case '=':
		l.advance()
		switch l.current() {
		case '=':
			l.advance()
			token = Token{TknEq, "==", startLine, startColumn}
		case '>':
			l.advance()
			token = Token{TknFatArrow, "=>", startLine, startColumn}
		default:
			token = Token{TknAssign, "=", startLine, startColumn}
		}
	case '<':
		l.advance()
		switch l.current() {
		case '=':
			l.advance()
			token = Token{TknLe, "<=", startLine, startColumn}
		case '<':
			l.advance()
			token = Token{TknLeftShift, "<<", startLine, startColumn}
		default:
			token = Token{TknLt, "<", startLine, startColumn}
		}
	case '>':
		l.advance()
		switch l.current() {
		case '=':
			l.advance()
			token = Token{TknGe, ">=", startLine, startColumn}
		case '>':
			l.advance()
			token = Token{TknRightShift, ">>", startLine, startColumn}
		default:
			token = Token{TknGt, ">", startLine, startColumn}
		}
	case ':':
		l.advance()
		switch l.current() {
		case ':':
			l.advance()
			token = Token{TknDoubleColon, "::", startLine, startColumn}
		case '=':
			l.advance()
			token = Token{TknColonAssign, ":=", startLine, startColumn}
		default:
			token = Token{TknColon, ":", startLine, startColumn}
		}
	case '.':
		l.advance()
		switch l.current() {
		case '.':
			l.advance()
			if l.current() == '=' {
				l.advance()
				token = Token{TknDotDotEq, "..=", startLine, startColumn}
			} else {
				token = Token{TknDoubleDot, "..", startLine, startColumn}
			}
		default:
			token = Token{TknDot, ".", startLine, startColumn}
		}
	case '"':
		l.advance()
		text, err := l.readString(byte('"'))
		if err != nil {
			return Token{}, err
		}
		token = Token{TknString, text, startLine, startColumn}
	case '\'':
		l.advance()
		text, err := l.readString(byte('\''))
		if err != nil {
			return Token{}, err
		}
		token = Token{TknString, text, startLine, startColumn}
	case '`':
		l.advance()
		text, err := l.readRawString()
		if err != nil {
			return Token{}, err
		}
		token = Token{TknRawString, text, startLine, startColumn}
	default:
		if unicode.IsDigit(rune(ch)) {
			return l.readNumber(startLine, startColumn)
		} else if unicode.IsLetter(rune(ch)) || ch == '_' {
			return l.readIdentifier(startLine, startColumn)
		} else {
			return Token{}, fmt.Errorf("unexpected character at %d:%d: '%c'", l.line, l.column, ch)
		}
	}

	token.Line = startLine
	token.Column = startColumn
	if token.Text == "" {
		token.Text = string(l.input[startPos:l.pos])
	}

	return token, nil
}

func (l *Lexer) readIdentifier(line, column int) (Token, error) {
	start := l.pos

	for !l.isAtEnd() && (unicode.IsLetter(rune(l.current())) || unicode.IsDigit(rune(l.current())) || l.current() == '_') {
		l.advance()
	}

	ident := l.input[start:l.pos]

	// Check if it's a keyword
	if tknType, ok := l.keywords[ident]; ok {
		return Token{tknType, ident, line, column}, nil
	}

	return Token{TknIdentifier, ident, line, column}, nil
}

func (l *Lexer) readNumber(line, column int) (Token, error) {
	start := l.pos

	// 정수 부분
	for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
		l.advance()
	}

	// 부동소수점 확인
	if l.current() == '.' && l.isDigitAt(l.pos+1) {
		l.advance() // skip '.'

		for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
			l.advance()
		}

		return Token{TknFloat, l.input[start:l.pos], line, column}, nil
	}

	return Token{TknInteger, l.input[start:l.pos], line, column}, nil
}

func (l *Lexer) readString(quote byte) (string, error) {
	start := l.pos

	for !l.isAtEnd() && l.current() != quote {
		if l.current() == '\\' {
			l.advance()
			if !l.isAtEnd() {
				l.advance()
			}
		} else {
			if l.current() == '\n' {
				l.line++
				l.column = 0
			}
			l.advance()
		}
	}

	if l.isAtEnd() {
		return "", fmt.Errorf("unterminated string at line %d", l.line)
	}

	content := l.input[start:l.pos]
	l.advance() // skip closing quote

	return l.unescapeString(content), nil
}

func (l *Lexer) readRawString() (string, error) {
	start := l.pos

	for !l.isAtEnd() && l.current() != '`' {
		if l.current() == '\n' {
			l.line++
			l.column = 0
		}
		l.advance()
	}

	if l.isAtEnd() {
		return "", fmt.Errorf("unterminated raw string at line %d", l.line)
	}

	content := l.input[start:l.pos]
	l.advance() // skip closing backtick

	return content, nil
}

func (l *Lexer) unescapeString(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n':
				result.WriteByte('\n')
				i += 2
			case 't':
				result.WriteByte('\t')
				i += 2
			case 'r':
				result.WriteByte('\r')
				i += 2
			case '\\':
				result.WriteByte('\\')
				i += 2
			case '"':
				result.WriteByte('"')
				i += 2
			case '\'':
				result.WriteByte('\'')
				i += 2
			default:
				result.WriteByte(s[i+1])
				i += 2
			}
		} else {
			result.WriteByte(s[i])
			i++
		}
	}
	return result.String()
}

func (l *Lexer) skipWhitespaceAndComments() {
	for !l.isAtEnd() {
		switch l.current() {
		case ' ', '\t', '\r':
			l.advance()
		case '\n':
			l.line++
			l.column = 0
			l.advance()
		case '/' :
			if l.peekNext() == '/' {
				// 한 줄 주석
				for !l.isAtEnd() && l.current() != '\n' {
					l.advance()
				}
			} else if l.peekNext() == '*' {
				// 블록 주석
				l.advance()
				l.advance()
				for !l.isAtEnd() {
					if l.current() == '*' && l.peekNext() == '/' {
						l.advance()
						l.advance()
						break
					}
					if l.current() == '\n' {
						l.line++
						l.column = 0
					}
					l.advance()
				}
			} else {
				return
			}
		default:
			return
		}
	}
}

func (l *Lexer) current() byte {
	if l.isAtEnd() {
		return 0
	}
	return l.input[l.pos]
}

func (l *Lexer) peekNext() byte {
	if l.pos+1 >= len(l.input) {
		return 0
	}
	return l.input[l.pos+1]
}

func (l *Lexer) isDigitAt(pos int) bool {
	if pos >= len(l.input) {
		return false
	}
	return unicode.IsDigit(rune(l.input[pos]))
}

func (l *Lexer) advance() {
	if !l.isAtEnd() {
		l.pos++
		l.column++
	}
}

func (l *Lexer) isAtEnd() bool {
	return l.pos >= len(l.input)
}

// Package codegen implements code generation from AST to C
package codegen

import (
	"fmt"
	"strings"

	"fv2-lang/internal/ast"
)

// Generator generates C code from an AST
type Generator struct {
	code          strings.Builder
	indent        int
	VarCounter    int
	functionStack []string // 현재 함수 스택
}

// New creates a new code generator
func New() *Generator {
	return &Generator{
		VarCounter:    0,
		functionStack: []string{},
	}
}

// Generate generates C code from a program AST
func (g *Generator) Generate(program *ast.Program) (string, error) {
	// Header files
	g.writeLine("#include <stdio.h>")
	g.writeLine("#include <stdlib.h>")
	g.writeLine("#include <string.h>")
	g.writeLine("#include <stdbool.h>")
	g.writeLine("")

	// Forward declarations for functions
	for _, def := range program.Definitions {
		if fn, ok := def.(*ast.FunctionDef); ok {
			g.writeFunctionDeclaration(fn)
		}
	}
	g.writeLine("")

	// Type definitions (structs, etc)
	for _, def := range program.Definitions {
		switch d := def.(type) {
		case *ast.StructDef:
			g.writeStructDefinition(d)
		case *ast.TypeDef:
			g.writeTypeDefinition(d)
		}
	}
	g.writeLine("")

	// Function implementations
	for _, def := range program.Definitions {
		if fn, ok := def.(*ast.FunctionDef); ok {
			g.writeFunctionDefinition(fn)
			g.writeLine("")
		}
	}

	// Main function
	g.writeLine("int main() {")
	g.indent++

	for _, stmt := range program.MainBody {
		g.generateStatement(stmt)
	}

	g.writeLine("return 0;")
	g.indent--
	g.writeLine("}")

	return g.code.String(), nil
}

// writeFunctionDeclaration writes forward declaration
func (g *Generator) writeFunctionDeclaration(fn *ast.FunctionDef) {
	params := g.generateParameterList(fn.Parameters)
	returnType := g.generateType(fn.ReturnType)
	g.writeLine(fmt.Sprintf("%s %s(%s);", returnType, fn.Name, params))
}

// writeStructDefinition writes struct definition
func (g *Generator) writeStructDefinition(str *ast.StructDef) {
	g.writeLine(fmt.Sprintf("struct %s {", str.Name))
	g.indent++

	for _, field := range str.Fields {
		fieldType := g.generateType(field.Type)
		g.writeLine(fmt.Sprintf("%s %s;", fieldType, field.Name))
	}

	g.indent--
	g.writeLine("};")
}

// writeTypeDefinition writes type alias
func (g *Generator) writeTypeDefinition(td *ast.TypeDef) {
	// For now, just skip type aliases (they're compile-time constructs)
	_ = td
}

// writeFunctionDefinition writes complete function
func (g *Generator) writeFunctionDefinition(fn *ast.FunctionDef) {
	g.functionStack = append(g.functionStack, fn.Name)

	params := g.generateParameterList(fn.Parameters)
	returnType := g.generateType(fn.ReturnType)

	g.writeLine(fmt.Sprintf("%s %s(%s) {", returnType, fn.Name, params))
	g.indent++

	for _, stmt := range fn.Body {
		g.generateStatement(stmt)
	}

	// Add return statement if not present
	if len(fn.Body) == 0 || !g.endsWithReturn(fn.Body) {
		if returnType == "void" {
			g.writeLine("return;")
		} else {
			g.writeLine(fmt.Sprintf("return 0; // %s", returnType))
		}
	}

	g.indent--
	g.writeLine("}")

	g.functionStack = g.functionStack[:len(g.functionStack)-1]
}

// generateParameterList generates parameter list for C
func (g *Generator) generateParameterList(params []ast.Parameter) string {
	if len(params) == 0 {
		return "void"
	}

	var parts []string
	for _, param := range params {
		paramType := g.generateType(param.Type)
		parts = append(parts, fmt.Sprintf("%s %s", paramType, param.Name))
	}

	return strings.Join(parts, ", ")
}

// generateType converts AST type to C type
func (g *Generator) generateType(t *ast.Type) string {
	if t == nil {
		return "void"
	}

	if t.IsArray {
		elemType := g.generateType(t.ElementType)
		return fmt.Sprintf("%s*", elemType) // Array as pointer
	}

	switch t.Name {
	case "i64":
		return "long long"
	case "f64":
		return "double"
	case "string":
		return "char*"
	case "bool":
		return "bool"
	case "none":
		return "void"
	default:
		return t.Name // struct name or custom type
	}
}

// generateStatement generates C code for a statement
func (g *Generator) generateStatement(stmt ast.Statement) {
	switch s := stmt.(type) {
	case *ast.LetStatement:
		g.generateLetStatement(s)
	case *ast.ConstStatement:
		g.generateConstStatement(s)
	case *ast.IfStatement:
		g.generateIfStatement(s)
	case *ast.ForStatement:
		g.generateForStatement(s)
	case *ast.ForRangeStatement:
		g.generateForRangeStatement(s)
	case *ast.ReturnStatement:
		g.generateReturnStatement(s)
	case *ast.ExpressionStatement:
		g.generateExpressionStatement(s)
	case *ast.MatchStatement:
		g.generateMatchStatement(s)
	case *ast.BlockStatement:
		g.generateBlockStatement(s)
	}
}

// generateLetStatement generates let binding
func (g *Generator) generateLetStatement(let *ast.LetStatement) {
	varType := "auto" // C11 auto-type inference
	if let.Type != nil {
		varType = g.generateType(let.Type)
	}

	initValue := g.generateExpression(let.Init)
	g.writeLine(fmt.Sprintf("%s %s = %s;", varType, let.Name, initValue))
}

// generateConstStatement generates const binding
func (g *Generator) generateConstStatement(const_ *ast.ConstStatement) {
	varType := "const int" // C const
	if const_.Type != nil {
		varType = fmt.Sprintf("const %s", g.generateType(const_.Type))
	}

	initValue := g.generateExpression(const_.Value)
	g.writeLine(fmt.Sprintf("%s %s = %s;", varType, const_.Name, initValue))
}

// generateIfStatement generates if-else statement
func (g *Generator) generateIfStatement(ifStmt *ast.IfStatement) {
	cond := g.generateExpression(ifStmt.Condition)
	g.writeLine(fmt.Sprintf("if (%s) {", cond))
	g.indent++

	for _, stmt := range ifStmt.ThenBody {
		g.generateStatement(stmt)
	}

	g.indent--

	if len(ifStmt.ElseBody) > 0 {
		g.writeLine("} else {")
		g.indent++

		for _, stmt := range ifStmt.ElseBody {
			g.generateStatement(stmt)
		}

		g.indent--
	}

	g.writeLine("}")
}

// generateForStatement generates for loop
func (g *Generator) generateForStatement(forStmt *ast.ForStatement) {
	// for i in iterator -> convert to C for loop
	// This is a simplified implementation
	g.writeLine("// TODO: for statement")
}

// generateForRangeStatement generates for-range loop
func (g *Generator) generateForRangeStatement(forStmt *ast.ForRangeStatement) {
	start := g.generateExpression(forStmt.Start)
	end := g.generateExpression(forStmt.End)

	g.writeLine(fmt.Sprintf("for (long long %s = %s; %s < %s; %s++) {",
		forStmt.Variable, start, forStmt.Variable, end, forStmt.Variable))
	g.indent++

	for _, stmt := range forStmt.Body {
		g.generateStatement(stmt)
	}

	g.indent--
	g.writeLine("}")
}

// generateReturnStatement generates return statement
func (g *Generator) generateReturnStatement(ret *ast.ReturnStatement) {
	if ret.Value != nil {
		value := g.generateExpression(ret.Value)
		g.writeLine(fmt.Sprintf("return %s;", value))
	} else {
		g.writeLine("return;")
	}
}

// generateExpressionStatement generates expression statement
func (g *Generator) generateExpressionStatement(expr *ast.ExpressionStatement) {
	code := g.generateExpression(expr.Expression)
	g.writeLine(fmt.Sprintf("%s;", code))
}

// generateMatchStatement generates match statement (as if-else chain)
func (g *Generator) generateMatchStatement(match *ast.MatchStatement) {
	// Convert match to if-else chain for now
	_ = g.generateExpression(match.Expression)

	for i, arm := range match.Arms {
		if i == 0 {
			g.writeLine(fmt.Sprintf("if (1) { // match arm %d", i))
		} else {
			g.writeLine("} else {")
		}
		g.indent++

		for _, stmt := range arm.Body {
			g.generateStatement(stmt)
		}

		g.indent--
	}

	if len(match.Arms) > 0 {
		g.writeLine("}")
	}
}

// generateBlockStatement generates block statement
func (g *Generator) generateBlockStatement(block *ast.BlockStatement) {
	g.writeLine("{")
	g.indent++

	for _, stmt := range block.Statements {
		g.generateStatement(stmt)
	}

	g.indent--
	g.writeLine("}")
}

// generateExpression generates C code for expression
func (g *Generator) generateExpression(expr ast.Expression) string {
	switch e := expr.(type) {
	case *ast.IntegerLiteral:
		return fmt.Sprintf("%d", e.Value)
	case *ast.FloatLiteral:
		return fmt.Sprintf("%g", e.Value)
	case *ast.StringLiteral:
		return fmt.Sprintf("\"%s\"", escapeString(e.Value))
	case *ast.BoolLiteral:
		if e.Value {
			return "true"
		}
		return "false"
	case *ast.NoneLiteral:
		return "NULL"
	case *ast.Identifier:
		return e.Name
	case *ast.BinaryExpression:
		return g.generateBinaryExpression(e)
	case *ast.UnaryExpression:
		return g.generateUnaryExpression(e)
	case *ast.CallExpression:
		return g.generateCallExpression(e)
	case *ast.ArrayExpression:
		return g.generateArrayExpression(e)
	case *ast.FieldExpression:
		return g.generateFieldExpression(e)
	case *ast.IndexExpression:
		return g.generateIndexExpression(e)
	case *ast.IfExpression:
		return g.generateIfExpression(e)
	}

	return "0"
}

// generateBinaryExpression generates binary operation
func (g *Generator) generateBinaryExpression(bin *ast.BinaryExpression) string {
	left := g.generateExpression(bin.Left)
	right := g.generateExpression(bin.Right)

	switch bin.Operator {
	case "..":
		// Range operator - not directly used in C expressions
		return fmt.Sprintf("range(%s, %s)", left, right)
	default:
		return fmt.Sprintf("(%s %s %s)", left, bin.Operator, right)
	}
}

// generateUnaryExpression generates unary operation
func (g *Generator) generateUnaryExpression(unary *ast.UnaryExpression) string {
	operand := g.generateExpression(unary.Operand)
	return fmt.Sprintf("(%s%s)", unary.Operator, operand)
}

// generateCallExpression generates function call
func (g *Generator) generateCallExpression(call *ast.CallExpression) string {
	fn := g.generateExpression(call.Function)

	var args []string
	for _, arg := range call.Arguments {
		args = append(args, g.generateExpression(arg))
	}

	return fmt.Sprintf("%s(%s)", fn, strings.Join(args, ", "))
}

// generateArrayExpression generates array literal
func (g *Generator) generateArrayExpression(arr *ast.ArrayExpression) string {
	// Arrays in C: create as pointer allocation
	if len(arr.Elements) == 0 {
		return "NULL"
	}

	// For now, return a simple representation
	var elems []string
	for _, elem := range arr.Elements {
		elems = append(elems, g.generateExpression(elem))
	}

	return fmt.Sprintf("{%s}", strings.Join(elems, ", "))
}

// generateFieldExpression generates struct field access
func (g *Generator) generateFieldExpression(field *ast.FieldExpression) string {
	obj := g.generateExpression(field.Object)
	return fmt.Sprintf("%s.%s", obj, field.Field)
}

// generateIndexExpression generates array indexing
func (g *Generator) generateIndexExpression(index *ast.IndexExpression) string {
	obj := g.generateExpression(index.Object)
	idx := g.generateExpression(index.Index)
	return fmt.Sprintf("%s[%s]", obj, idx)
}

// generateIfExpression generates if as expression
func (g *Generator) generateIfExpression(ifExpr *ast.IfExpression) string {
	cond := g.generateExpression(ifExpr.Condition)
	then := g.generateExpression(ifExpr.ThenExpr)

	if ifExpr.ElseExpr != nil {
		else_ := g.generateExpression(ifExpr.ElseExpr)
		return fmt.Sprintf("(%s ? %s : %s)", cond, then, else_)
	}

	return fmt.Sprintf("(%s ? %s : 0)", cond, then)
}

// Helper functions

// writeLine writes a line with proper indentation
func (g *Generator) writeLine(line string) {
	indent := strings.Repeat("  ", g.indent)
	g.code.WriteString(indent + line + "\n")
}

// endsWithReturn checks if statements end with return
func (g *Generator) endsWithReturn(stmts []ast.Statement) bool {
	if len(stmts) == 0 {
		return false
	}

	_, ok := stmts[len(stmts)-1].(*ast.ReturnStatement)
	return ok
}

// escapeString escapes special characters in strings
func escapeString(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\t", "\\t")
	return s
}

