    28→// Parse parses tokens into an AST
    29→func (p *Parser) Parse() (*ast.Program, error) {
    30→	var definitions []ast.Definition
    31→	var mainBody []ast.Statement
    32→
    33→	for !p.isAtEnd() {
    34→		if p.match(lexer.TknEof) {
    35→			break
    36→		}
    37→
    38→		if p.check(lexer.TknFn) {
    39→			def, err := p.parseFunctionDef()
    40→			if err != nil {
    41→				return nil, err
    42→			}
    43→			if def != nil {
    44→				definitions = append(definitions, def)
    45→			}
    46→		} else if p.check(lexer.TknType) {
    47→			def, err := p.parseTypeDef()
    48→			if err != nil {
    49→				return nil, err
    50→			}
    51→			if def != nil {
    52→				definitions = append(definitions, def)
    53→			}
    54→		} else if p.check(lexer.TknStruct) {
    55→			def, err := p.parseStructDef()
    56→			if err != nil {
    57→				return nil, err
    58→			}
    59→			if def != nil {
    60→				definitions = append(definitions, def)
    61→			}
    62→		} else {
    63→			stmt, err := p.parseStatement()
    64→			if err != nil {
    65→				return nil, err
    66→			}
    67→			if stmt != nil {
    68→				mainBody = append(mainBody, stmt)
    69→			}
    70→		}
    71→	}
    72→
    73→	return &ast.Program{
    74→		Definitions: definitions,
    75→		MainBody:    mainBody,
    76→	}, nil
    77→}
