    79→// parseFunctionDef parses a function definition
    80→func (p *Parser) parseFunctionDef() (*ast.FunctionDef, error) {
    81→	if !p.match(lexer.TknFn) {
    82→		return nil, nil
    83→	}
    84→
    85→	name := p.current().Text
    86→	if !p.match(lexer.TknIdentifier) {
    87→		return nil, fmt.Errorf("expected function name at %d:%d", p.current().Line, p.current().Column)
    88→	}
    89→
    90→	if !p.match(lexer.TknLParen) {
    91→		return nil, fmt.Errorf("expected '(' at %d:%d", p.current().Line, p.current().Column)
    92→	}
    93→
    94→	// Parse parameters
    95→	var params []ast.Parameter
    96→	if !p.check(lexer.TknRParen) {
    97→		for {
    98→			paramName := p.current().Text
    99→			if !p.match(lexer.TknIdentifier) {
   100→				return nil, fmt.Errorf("expected parameter name at %d:%d", p.current().Line, p.current().Column)
   101→			}
   102→
   103→			var paramType *ast.Type
   104→			if p.match(lexer.TknColon) {
   105→				// Type annotation
   106→				paramType = p.parseType()
   107→			}
   108→
   109→			params = append(params, ast.Parameter{
   110→				Name: paramName,
   111→				Type: paramType,
   112→			})
   113→
   114→			if !p.match(lexer.TknComma) {
   115→				break
   116→			}
   117→		}
   118→	}
   119→
   120→	if !p.match(lexer.TknRParen) {
   121→		return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   122→	}
   123→
   124→	// Parse return type (V syntax: type directly after params, no ->)
   125→	var returnType *ast.Type
   126→	if !p.check(lexer.TknLBrace) && !p.isAtEnd() {
   127→		// Look ahead to see if next is a type (identifier or keyword type)
   128→		if p.check(lexer.TknIdentifier) || p.isPrimitiveType() {
   129→			returnType = p.parseType()
   130→		}
   131→	}
   132→
   133→	// Parse body
   134→	if !p.match(lexer.TknLBrace) {
   135→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   136→	}
   137→
   138→	var body []ast.Statement
   139→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   140→		stmt, err := p.parseStatement()
   141→		if err != nil {
   142→			return nil, err
   143→		}
   144→		if stmt != nil {
   145→			body = append(body, stmt)
   146→		}
   147→	}
   148→
   149→	if !p.match(lexer.TknRBrace) {
   150→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   151→	}
   152→
   153→	return &ast.FunctionDef{
   154→		Name:       name,
   155→		Parameters: params,
   156→		ReturnType: returnType,
   157→		Body:       body,
   158→	}, nil
   159→}
