   161→// parseTypeDef parses a type definition
   162→// V syntax: type UserId = i64
   163→func (p *Parser) parseTypeDef() (*ast.TypeDef, error) {
   164→	if !p.match(lexer.TknType) {
   165→		return nil, nil
   166→	}
   167→
   168→	name := p.current().Text
   169→	if !p.match(lexer.TknIdentifier) {
   170→		return nil, fmt.Errorf("expected type name at %d:%d", p.current().Line, p.current().Column)
   171→	}
   172→
   173→	if !p.match(lexer.TknAssign) {
   174→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   175→	}
   176→
   177→	// Parse the underlying type (simple type alias)
   178→	underlyingType := p.parseType()
   179→
   180→	return &ast.TypeDef{
   181→		Name: name,
   182→		Fields: []ast.Field{
   183→			{
   184→				Name: "value",
   185→				Type: underlyingType,
   186→			},
   187→		},
   188→	}, nil
   189→}
