   191→// parseStructDef parses a struct definition
   192→// V syntax: struct Point { x i64, y i64 }
   193→// Field syntax: name type (no colon)
   194→func (p *Parser) parseStructDef() (*ast.StructDef, error) {
   195→	if !p.match(lexer.TknStruct) {
   196→		return nil, nil
   197→	}
   198→
   199→	name := p.current().Text
   200→	if !p.match(lexer.TknIdentifier) {
   201→		return nil, fmt.Errorf("expected struct name at %d:%d", p.current().Line, p.current().Column)
   202→	}
   203→
   204→	if !p.match(lexer.TknLBrace) {
   205→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   206→	}
   207→
   208→	var fields []ast.Field
   209→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   210→		isMutable := p.match(lexer.TknMut)
   211→
   212→		fieldName := p.current().Text
   213→		if !p.match(lexer.TknIdentifier) {
   214→			return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   215→		}
   216→
   217→		// V syntax: field type (space-separated, no colon)
   218→		fieldType := p.parseType()
   219→
   220→		fields = append(fields, ast.Field{
   221→			Name:    fieldName,
   222→			Type:    fieldType,
   223→			Mutable: isMutable,
   224→		})
   225→
   226→		if !p.match(lexer.TknComma) {
   227→			break
   228→		}
   229→	}
   230→
   231→	if !p.match(lexer.TknRBrace) {
   232→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   233→	}
   234→
   235→	return &ast.StructDef{
   236→		Name:   name,
   237→		Fields: fields,
   238→	}, nil
   239→}
