   241→// parseStatement parses a statement
   242→func (p *Parser) parseStatement() (ast.Statement, error) {
   243→	if p.match(lexer.TknLet) {
   244→		return p.parseLetStatement()
   245→	}
   246→	if p.match(lexer.TknConst) {
   247→		return p.parseConstStatement()
   248→	}
   249→	if p.match(lexer.TknIf) {
   250→		return p.parseIfStatement()
   251→	}
   252→	if p.match(lexer.TknFor) {
   253→		return p.parseForStatement()
   254→	}
   255→	if p.match(lexer.TknMatch) {
   256→		return p.parseMatchStatement()
   257→	}
   258→	if p.match(lexer.TknReturn) {
   259→		return p.parseReturnStatement()
   260→	}
   261→	if p.match(lexer.TknLBrace) {
   262→		return p.parseBlockStatement()
   263→	}
   264→
   265→	// Expression statement
   266→	expr, err := p.parseExpression()
   267→	if err != nil {
   268→		return nil, err
   269→	}
   270→
   271→	// Consume optional semicolon
   272→	p.match(lexer.TknSemicolon)
   273→
   274→	return &ast.ExpressionStatement{Expression: expr}, nil
   275→}
