   277→// parseLetStatement parses a let binding
   278→func (p *Parser) parseLetStatement() (ast.Statement, error) {
   279→	isMutable := p.match(lexer.TknMut)
   280→
   281→	name := p.current().Text
   282→	if !p.match(lexer.TknIdentifier) {
   283→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   284→	}
   285→
   286→	var varType *ast.Type
   287→	if p.match(lexer.TknColon) {
   288→		varType = p.parseType()
   289→	}
   290→
   291→	var init ast.Expression
   292→	if p.match(lexer.TknAssign) || p.match(lexer.TknColonAssign) {
   293→		var err error
   294→		init, err = p.parseExpression()
   295→		if err != nil {
   296→			return nil, err
   297→		}
   298→	}
   299→
   300→	p.match(lexer.TknSemicolon)
   301→
   302→	return &ast.LetStatement{
   303→		Name:    name,
   304→		Type:    varType,
   305→		Init:    init,
   306→		Mutable: isMutable,
   307→	}, nil
   308→}
