   340→// parseIfStatement parses an if statement
   341→func (p *Parser) parseIfStatement() (ast.Statement, error) {
   342→	cond, err := p.parseExpression()
   343→	if err != nil {
   344→		return nil, err
   345→	}
   346→
   347→	if !p.match(lexer.TknLBrace) {
   348→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   349→	}
   350→
   351→	var thenBody []ast.Statement
   352→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   353→		stmt, err := p.parseStatement()
   354→		if err != nil {
   355→			return nil, err
   356→		}
   357→		if stmt != nil {
   358→			thenBody = append(thenBody, stmt)
   359→		}
   360→	}
   361→
   362→	if !p.match(lexer.TknRBrace) {
   363→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   364→	}
   365→
   366→	var elseBody []ast.Statement
   367→	if p.match(lexer.TknElse) {
   368→		if p.match(lexer.TknLBrace) {
   369→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   370→				stmt, err := p.parseStatement()
   371→				if err != nil {
   372→					return nil, err
   373→				}
   374→				if stmt != nil {
   375→					elseBody = append(elseBody, stmt)
   376→				}
   377→			}
   378→
   379→			if !p.match(lexer.TknRBrace) {
   380→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   381→			}
   382→		}
   383→	}
   384→
   385→	return &ast.IfStatement{
   386→		Condition: cond,
   387→		ThenBody:  thenBody,
   388→		ElseBody:  elseBody,
   389→	}, nil
   390→}
