   392→// parseForStatement parses a for loop
   393→func (p *Parser) parseForStatement() (ast.Statement, error) {
   394→	varName := p.current().Text
   395→	if !p.match(lexer.TknIdentifier) {
   396→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   397→	}
   398→
   399→	if !p.match(lexer.TknIn) {
   400→		return nil, fmt.Errorf("expected 'in' at %d:%d", p.current().Line, p.current().Column)
   401→	}
   402→
   403→	iter, err := p.parseExpression()
   404→	if err != nil {
   405→		return nil, err
   406→	}
   407→
   408→	if !p.match(lexer.TknLBrace) {
   409→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   410→	}
   411→
   412→	var body []ast.Statement
   413→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   414→		stmt, err := p.parseStatement()
   415→		if err != nil {
   416→			return nil, err
   417→		}
   418→		if stmt != nil {
   419→			body = append(body, stmt)
   420→		}
   421→	}
   422→
   423→	if !p.match(lexer.TknRBrace) {
   424→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   425→	}
   426→
   427→	// Check if iter is a range (BinaryExpression with .. operator)
   428→	if binExpr, ok := iter.(*ast.BinaryExpression); ok && binExpr.Operator == ".." {
   429→		return &ast.ForRangeStatement{
   430→			Variable: varName,
   431→			Start:    binExpr.Left,
   432→			End:      binExpr.Right,
   433→			Body:     body,
   434→		}, nil
   435→	}
   436→
   437→	return &ast.ForStatement{
   438→		Variable: varName,
   439→		Iterator: iter,
   440→		Body:     body,
   441→	}, nil
   442→}
