   444→// parseMatchStatement parses a match statement
   445→func (p *Parser) parseMatchStatement() (ast.Statement, error) {
   446→	expr, err := p.parseExpression()
   447→	if err != nil {
   448→		return nil, err
   449→	}
   450→
   451→	if !p.match(lexer.TknLBrace) {
   452→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   453→	}
   454→
   455→	var arms []ast.MatchArm
   456→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   457→		// Parse pattern
   458→		pattern, err := p.parsePattern()
   459→		if err != nil {
   460→			return nil, err
   461→		}
   462→
   463→		if !p.match(lexer.TknFatArrow) {
   464→			return nil, fmt.Errorf("expected '=>' at %d:%d", p.current().Line, p.current().Column)
   465→		}
   466→
   467→		// Parse body
   468→		var body []ast.Statement
   469→		if p.match(lexer.TknLBrace) {
   470→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   471→				stmt, err := p.parseStatement()
   472→				if err != nil {
   473→					return nil, err
   474→				}
   475→				if stmt != nil {
   476→					body = append(body, stmt)
   477→				}
   478→			}
   479→			if !p.match(lexer.TknRBrace) {
   480→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   481→			}
   482→		} else {
   483→			stmt, err := p.parseStatement()
   484→			if err != nil {
   485→				return nil, err
   486→			}
   487→			if stmt != nil {
   488→				body = append(body, stmt)
   489→			}
   490→		}
   491→
   492→		arms = append(arms, ast.MatchArm{
   493→			Pattern: pattern,
   494→			Body:    body,
   495→		})
   496→
   497→		if !p.match(lexer.TknComma) {
   498→			break
   499→		}
   500→	}
   501→
   502→	if !p.match(lexer.TknRBrace) {
   503→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   504→	}
   505→
   506→	return &ast.MatchStatement{
   507→		Expression: expr,
   508→		Arms:       arms,
   509→	}, nil
   510→}
   511→
   512→// parseReturnStatement parses a return statement
   513→func (p *Parser) parseReturnStatement() (ast.Statement, error) {
   514→	var value ast.Expression
   515→	if !p.check(lexer.TknSemicolon) && !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   516→		var err error
   517→		value, err = p.parseExpression()
   518→		if err != nil {
   519→			return nil, err
   520→		}
   521→	}
   522→
   523→	p.match(lexer.TknSemicolon)
   524→
   525→	return &ast.ReturnStatement{Value: value}, nil
   526→}
