   528→// parseBlockStatement parses a block statement
   529→func (p *Parser) parseBlockStatement() (ast.Statement, error) {
   530→	var statements []ast.Statement
   531→
   532→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   533→		stmt, err := p.parseStatement()
   534→		if err != nil {
   535→			return nil, err
   536→		}
   537→		if stmt != nil {
   538→			statements = append(statements, stmt)
   539→		}
   540→	}
   541→
   542→	if !p.match(lexer.TknRBrace) {
   543→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   544→	}
   545→
   546→	return &ast.BlockStatement{Statements: statements}, nil
