   554→// parseBinaryExpression parses binary expressions with precedence
   555→func (p *Parser) parseBinaryExpression(minPrec int) (ast.Expression, error) {
   556→	left, err := p.parseUnary()
   557→	if err != nil {
   558→		return nil, err
   559→	}
   560→
   561→	for {
   562→		if p.isAtEnd() || !p.isOperator(p.current().Type) {
   563→			break
   564→		}
   565→
   566→		op := p.current()
   567→		prec := getPrecedence(op.Type)
   568→		if prec < minPrec {
   569→			break
   570→		}
   571→
   572→		p.advance()
   573→
   574→		right, err := p.parseBinaryExpression(prec + 1)
   575→		if err != nil {
   576→			return nil, err
   577→		}
   578→
   579→		left = &ast.BinaryExpression{
   580→			Left:     left,
   581→			Operator: op.Text,
   582→			Right:    right,
   583→		}
   584→	}
   585→
   586→	return left, nil
   587→}
