   589→// parseUnary parses unary expressions
   590→func (p *Parser) parseUnary() (ast.Expression, error) {
   591→	if p.match(lexer.TknNot) {
   592→		operand, err := p.parseUnary()
   593→		if err != nil {
   594→			return nil, err
   595→		}
   596→		return &ast.UnaryExpression{
   597→			Operator: "!",
   598→			Operand:  operand,
   599→		}, nil
   600→	}
   601→
   602→	if p.match(lexer.TknMinus) {
   603→		operand, err := p.parseUnary()
   604→		if err != nil {
   605→			return nil, err
   606→		}
   607→		return &ast.UnaryExpression{
   608→			Operator: "-",
   609→			Operand:  operand,
   610→		}, nil
   611→	}
   612→
   613→	if p.match(lexer.TknAmpersand) {
   614→		operand, err := p.parseUnary()
   615→		if err != nil {
   616→			return nil, err
   617→		}
   618→		return &ast.UnaryExpression{
   619→			Operator: "&",
   620→			Operand:  operand,
   621→		}, nil
   622→	}
   623→
   624→	return p.parsePostfix()
   625→}
   626→
   627→// parsePostfix parses postfix expressions
   628→func (p *Parser) parsePostfix() (ast.Expression, error) {
   629→	expr, err := p.parsePrimary()
   630→	if err != nil {
   631→		return nil, err
   632→	}
   633→
   634→	for {
   635→		if p.match(lexer.TknLParen) {
   636→			// Function call
   637→			var args []ast.Expression
   638→			if !p.check(lexer.TknRParen) {
   639→				for {
   640→					arg, err := p.parseExpression()
   641→					if err != nil {
   642→						return nil, err
   643→					}
   644→					args = append(args, arg)
   645→
   646→					if !p.match(lexer.TknComma) {
   647→						break
   648→					}
   649→				}
   650→			}
   651→
   652→			if !p.match(lexer.TknRParen) {
   653→				return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   654→			}
   655→
   656→			expr = &ast.CallExpression{
   657→				Function:  expr,
   658→				Arguments: args,
   659→			}
   660→		} else if p.match(lexer.TknDot) {
   661→			// Field access or method call
   662→			fieldName := p.current().Text
   663→			if !p.match(lexer.TknIdentifier) {
   664→				return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   665→			}
   666→
   667→			if p.match(lexer.TknLParen) {
   668→				// Method call
   669→				var args []ast.Expression
   670→				if !p.check(lexer.TknRParen) {
   671→					for {
   672→						arg, err := p.parseExpression()
   673→						if err != nil {
   674→							return nil, err
   675→						}
   676→						args = append(args, arg)
   677→
   678→						if !p.match(lexer.TknComma) {
   679→							break
   680→						}
   681→					}
   682→				}
   683→
   684→				if !p.match(lexer.TknRParen) {
   685→					return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   686→				}
   687→
   688→				expr = &ast.MethodCallExpression{
   689→					Object:    expr,
   690→					Method:    fieldName,
   691→					Arguments: args,
   692→				}
   693→			} else {
   694→				// Field access
   695→				expr = &ast.FieldExpression{
   696→					Object: expr,
   697→					Field:  fieldName,
   698→				}
   699→			}
   700→		} else if p.match(lexer.TknLBracket) {
   701→			// Index access
   702→			index, err := p.parseExpression()
   703→			if err != nil {
   704→				return nil, err
   705→			}
   706→
   707→			if !p.match(lexer.TknRBracket) {
   708→				return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   709→			}
   710→
   711→			expr = &ast.IndexExpression{
   712→				Object: expr,
   713→				Index:  index,
   714→			}
   715→		} else if p.match(lexer.TknQuestion) {
   716→			// Error propagation
   717→			expr = &ast.ErrorPropagation{Expression: expr}
   718→		} else {
   719→			break
   720→		}
   721→	}
   722→
   723→	return expr, nil
   724→}
   725→
   726→// parsePrimary parses primary expressions
   727→func (p *Parser) parsePrimary() (ast.Expression, error) {
   728→	// Literals
   729→	if p.match(lexer.TknInteger) {
   730→		val, err := strconv.ParseInt(p.previous().Text, 10, 64)
   731→		if err != nil {
   732→			return nil, fmt.Errorf("invalid integer: %s", p.previous().Text)
   733→		}
   734→		return &ast.IntegerLiteral{Value: val}, nil
   735→	}
   736→
   737→	if p.match(lexer.TknFloat) {
   738→		val, err := strconv.ParseFloat(p.previous().Text, 64)
   739→		if err != nil {
   740→			return nil, fmt.Errorf("invalid float: %s", p.previous().Text)
   741→		}
   742→		return &ast.FloatLiteral{Value: val}, nil
   743→	}
   744→
   745→	if p.match(lexer.TknString) {
   746→		return &ast.StringLiteral{Value: p.previous().Text}, nil
   747→	}
   748→
   749→	if p.match(lexer.TknTrue) {
   750→		return &ast.BoolLiteral{Value: true}, nil
   751→	}
   752→
   753→	if p.match(lexer.TknFalse) {
   754→		return &ast.BoolLiteral{Value: false}, nil
   755→	}
   756→
   757→	if p.match(lexer.TknNone) {
   758→		return &ast.NoneLiteral{}, nil
   759→	}
   760→
   761→	if p.match(lexer.TknIdentifier) {
   762→		return &ast.Identifier{Name: p.previous().Text}, nil
   763→	}
   764→
   765→	if p.match(lexer.TknLBracket) {
   766→		// Array literal
   767→		var elements []ast.Expression
   768→		if !p.check(lexer.TknRBracket) {
   769→			for {
   770→				elem, err := p.parseExpression()
   771→				if err != nil {
   772→					return nil, err
   773→				}
   774→				elements = append(elements, elem)
   775→
   776→				if !p.match(lexer.TknComma) {
   777→					break
   778→				}
   779→			}
   780→		}
   781→
   782→		if !p.match(lexer.TknRBracket) {
   783→			return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   784→		}
   785→
   786→		return &ast.ArrayExpression{Elements: elements}, nil
   787→	}
   788→
   789→	if p.match(lexer.TknIf) {
   790→		// Parse if expression
   791→		cond, err := p.parseExpression()
   792→		if err != nil {
   793→			return nil, err
   794→		}
   795→
   796→		if !p.match(lexer.TknLBrace) {
   797→			return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   798→		}
   799→
   800→		thenExpr, err := p.parseExpression()
   801→		if err != nil {
   802→			return nil, err
   803→		}
   804→
   805→		if !p.match(lexer.TknRBrace) {
   806→			return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   807→		}
   808→
   809→		var elseExpr ast.Expression
   810→		if p.match(lexer.TknElse) {
   811→			if p.match(lexer.TknLBrace) {
   812→				var err error
   813→				elseExpr, err = p.parseExpression()
   814→				if err != nil {
   815→					return nil, err
   816→				}
   817→
   818→				if !p.match(lexer.TknRBrace) {
   819→					return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   820→				}
   821→			}
   822→		}
   823→
   824→		return &ast.IfExpression{
   825→			Condition: cond,
   826→			ThenExpr:  thenExpr,
   827→			ElseExpr:  elseExpr,
   828→		}, nil
   829→	}
   830→
   831→	if p.match(lexer.TknLParen) {
   832→		expr, err := p.parseExpression()
   833→		if err != nil {
   834→			return nil, err
   835→		}
   836→
   837→		if !p.match(lexer.TknRParen) {
   838→			return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   839→		}
   840→
   841→		return expr, nil
   842→	}
   843→
   844→	return nil, fmt.Errorf("unexpected token: %v at %d:%d", p.current().Type, p.current().Line, p.current().Column)
   845→}
   846→
   847→// parsePattern parses a pattern
   848→func (p *Parser) parsePattern() (ast.Pattern, error) {
   849→	if p.match(lexer.TknIdentifier) {
   850→		return &ast.IdentifierPattern{Name: p.previous().Text}, nil
   851→	}
   852→
   853→	if p.match(lexer.TknInteger) {
   854→		val, _ := strconv.ParseInt(p.previous().Text, 10, 64)
   855→		return &ast.LiteralPattern{Value: &ast.IntegerLiteral{Value: val}}, nil
   856→	}
   857→
   858→	if p.match(lexer.TknString) {
   859→		return &ast.LiteralPattern{Value: &ast.StringLiteral{Value: p.previous().Text}}, nil
   860→	}
   861→
   862→	if p.match(lexer.TknTilde) {
   863→		return &ast.WildcardPattern{}, nil
   864→	}
   865→
   866→	return nil, fmt.Errorf("unexpected pattern at %d:%d", p.current().Line, p.current().Column)
   867→}
   868→
   869→// parseType parses a type
   870→func (p *Parser) parseType() *ast.Type {
   871→	// Handle option types (?)
   872→	isOption := p.match(lexer.TknQuestion)
   873→
   874→	// Get base type
   875→	var typeName string
   876→	if p.match(lexer.TknIdentifier) {
   877→		typeName = p.previous().Text
   878→	} else {
   879→		typeName = "unknown"
   880→	}
   881→
   882→	// Handle array types (prefix [])
   883→	isArray := false
   884→	if p.check(lexer.TknLBracket) {
   885→		p.advance()
   886→		if p.match(lexer.TknRBracket) {
   887→			isArray = true
   888→		} else {
   889→			p.pos-- // backtrack
   890→		}
   891→	}
   892→
   893→	return &ast.Type{
   894→		Name:       typeName,
   895→		IsOption:   isOption,
   896→		IsArray:    isArray,
   897→		IsPrimitive: isPrimitiveType(typeName),
   898→	}
   899→}
   900→
   901→// Helper methods
   902→
   903→func (p *Parser) current() lexer.Token {
   904→	if p.pos < len(p.tokens) {
   905→		return p.tokens[p.pos]
   906→	}
   907→	return lexer.Token{Type: lexer.TknEof}
   908→}
   909→
   910→func (p *Parser) previous() lexer.Token {
   911→	if p.pos > 0 {
   912→		return p.tokens[p.pos-1]
   913→	}
   914→	return lexer.Token{Type: lexer.TknEof}
   915→}
   916→
   917→func (p *Parser) advance() lexer.Token {
   918→	curr := p.current()
   919→	if !p.isAtEnd() {
   920→		p.pos++
   921→	}
   922→	return curr
   923→}
   924→
   925→func (p *Parser) match(types ...lexer.TokenType) bool {
   926→	for _, t := range types {
   927→		if p.check(t) {
   928→			p.advance()
   929→			return true
   930→		}
   931→	}
   932→	return false
   933→}
   934→
   935→func (p *Parser) check(t lexer.TokenType) bool {
   936→	if p.isAtEnd() {
   937→		return false
   938→	}
   939→	return p.current().Type == t
   940→}
   941→
   942→func (p *Parser) isAtEnd() bool {
   943→	return p.current().Type == lexer.TknEof
   944→}
   945→
   946→func (p *Parser) isOperator(t lexer.TokenType) bool {
   947→	// Check if token is an operator
   948→	switch t {
   949→	case lexer.TknPlus, lexer.TknMinus, lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   950→		return true
   951→	case lexer.TknAmpersand, lexer.TknPipe, lexer.TknCaret, lexer.TknTilde:
   952→		return true
   953→	case lexer.TknLeftShift, lexer.TknRightShift:
   954→		return true
   955→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   956→		return true
   957→	case lexer.TknLogicalAnd, lexer.TknLogicalOr, lexer.TknNot:
   958→		return true
   959→	case lexer.TknDoubleDot:
   960→		return true
   961→	default:
   962→		return false
   963→	}
   964→}
   965→
   966→func getPrecedence(t lexer.TokenType) int {
   967→	switch t {
   968→	case lexer.TknLogicalOr:
   969→		return 1
   970→	case lexer.TknLogicalAnd:
   971→		return 2
   972→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   973→		return 3
   974→	case lexer.TknPlus, lexer.TknMinus:
   975→		return 4
   976→	case lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   977→		return 5
   978→	case lexer.TknCaret:
   979→		return 6
   980→	case lexer.TknDoubleDot:
   981→		return 3 // Same as comparison for range expressions
   982→	default:
   983→		return 0
   984→	}
   985→}
   986→
   987→func (p *Parser) isPrimitiveType() bool {
   988→	if p.current().Type == lexer.TknIdentifier {
   989→		return isPrimitiveType(p.current().Text)
   990→	}
   991→	// Also check for V primitive keywords
   992→	switch p.current().Type {
   993→	case lexer.TknTrue, lexer.TknFalse:
   994→		return true
   995→	}
   996→	return false
   997→}
   998→
   999→func isPrimitiveType(name string) bool {
  1000→	switch name {
  1001→	case "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "char", "int", "float":
  1002→		return true
  1003→	}
  1004→	return false
  1005→}
